<div class="field-row card" draggable="true" style="margin:12px 0;padding:14px">
    <input type="hidden" name="fields[{{ $index }}][id]" value="{{ $field['id'] ?? '' }}">
    <div class="field-row-actions"><button class="drag-handle" type="button" title="Trascina per riordinare" aria-label="Trascina per riordinare">Trascina</button><strong class="field-position">Campo</strong><button class="button small secondary move-up" type="button">Su</button><button class="button small secondary move-down" type="button">Giu</button></div>
    <div class="grid grid-3">
        <div class="field"><label>Chiave</label><input name="fields[{{ $index }}][key]" value="{{ $field['key'] ?? '' }}" placeholder="lotto" required></div>
        <div class="field"><label>Etichetta</label><input name="fields[{{ $index }}][label]" value="{{ $field['label'] ?? '' }}" placeholder="Lotto" required></div>
        <div class="field"><label>Tipo</label><select name="fields[{{ $index }}][input_type]"><option value="text" @selected(($field['input_type'] ?? '__TYPE__') === 'text')>Testo</option><option value="date" @selected(($field['input_type'] ?? '__TYPE__') === 'date')>Data</option><option value="number" @selected(($field['input_type'] ?? '__TYPE__') === 'number')>Numero</option></select></div>
        <div class="field"><label>Valore predefinito</label><input name="fields[{{ $index }}][default_value]" value="{{ $field['default_value'] ?? '' }}"></div>
        <div class="field"><label>Regole di validazione</label><input name="fields[{{ $index }}][validation_rules]" value="{{ $field['validation_rules'] ?? '' }}" placeholder="max:20"></div>
        <div class="field"><label>Obbligatorio</label><label class="checkbox"><input type="hidden" name="fields[{{ $index }}][is_required]" value="0"><input type="checkbox" name="fields[{{ $index }}][is_required]" value="1" @checked($field['is_required'] ?? true)> Sì</label></div>
    </div>
    <details class="layout-settings"><summary>Posizione e dimensioni nell'anteprima</summary><div class="grid grid-3" style="margin-top:12px"><div class="field"><label>X (px)</label><input class="layout-input" type="number" min="0" max="799" name="fields[{{ $index }}][layout_x]" value="{{ $field['layout_x'] ?? 20 }}" required></div><div class="field"><label>Y (px)</label><input class="layout-input" type="number" min="0" max="299" name="fields[{{ $index }}][layout_y]" value="{{ $field['layout_y'] ?? 20 }}" required></div><div class="field"><label>Larghezza (px)</label><input class="layout-input" type="number" min="20" max="800" name="fields[{{ $index }}][layout_width]" value="{{ $field['layout_width'] ?? 220 }}" required></div><div class="field"><label>Altezza (px)</label><input class="layout-input" type="number" min="20" max="300" name="fields[{{ $index }}][layout_height]" value="{{ $field['layout_height'] ?? 48 }}" required></div><div class="field"><label>Dimensione testo (px)</label><input class="layout-input" type="number" min="8" max="72" name="fields[{{ $index }}][font_size]" value="{{ $field['font_size'] ?? 24 }}" required></div></div></details>
    <button class="button small danger remove-field" type="button">Rimuovi campo</button>
</div>
